analyze.mjs.text:
// Classifies a fetched page's canonical-tag evidence (real HTTP responses,
// collected by probe.mjs's live requests or pasted in by hand) into named
// canonicalization misconfiguration patterns.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// What each finding means, and why it is evidence rather than an opinion:
//
//   no-canonical-tag            No <link rel="canonical"> tag in <head> at
//                                all. Not inherently wrong -- search engines
//                                infer one on their own -- but an explicit
//                                tag replaces their guess with yours.
//   multiple-conflicting-       Two or more canonical tags naming different
//   canonical                   URLs. Browsers and crawlers honor only the
//                                first and ignore the rest, so this is the
//                                page's own markup contradicting itself --
//                                commonly two systems (a CMS plugin and a
//                                hand-written template tag) both emitting one.
//   relative-canonical-url      The one canonical tag's href has no scheme
//                                and host. Google's own guidance is to use an
//                                absolute URL.
//   protocol-mismatch-canonical The canonical's scheme (http/https) differs
//                                from the scheme the page itself was served
//                                over -- often a leftover from a migration.
//   cross-domain-canonical      The canonical points at a different
//                                registrable domain. A real, supported
//                                pattern for syndicated content, and also
//                                exactly what a hardcoded staging URL or a
//                                copied template leaves behind -- either way
//                                it tells search engines to index the other
//                                domain's page instead of this one.
//   canonical-target-unreachable The canonical URL itself errors or 4xx/5xxs
//                                when fetched: it names a page to index that
//                                does not return usable content.
//   canonical-target-redirects  The canonical URL redirects before resolving.
//                                It should ideally point straight at the
//                                final resting URL.
//   canonical-target-noindex    The page the canonical points at carries a
//                                noindex directive itself -- a direct
//                                contradiction ("index this" pointing at a
//                                page that says "don't index me").
//
// Only the single-canonical-specific checks (relative/protocol/cross-domain)
// run when exactly one canonical link with an href is present: with zero,
// there is nothing to check; with two or more, `multiple-conflicting-
// canonical` already covers it and "which one would you even check" has no
// good answer.

function isAbsoluteUrl(href) {
  return /^[a-z][a-z0-9+.-]*:\/\//i.test((href || '').trim());
}

function normalizeForCompare(href) {
  return (href || '').trim().replace(/\/$/, '');
}

const TWO_LABEL_SUFFIXES = new Set(['co.uk', 'com.au', 'co.jp', 'com.br', 'co.nz', 'github.io']);

/** Good-enough eTLD+1 approximation for the "same domain" comparison this
 * check needs -- not a full public-suffix-list implementation, but it
 * correctly handles the handful of common two-label public suffixes a real
 * site (including this portfolio's own GitHub Pages host) could plausibly
 * hit, rather than reading "sub.example.co.uk" and "other.co.uk" as the
 * same domain. */
function registrableHost(hostname) {
  const parts = (hostname || '').toLowerCase().split('.').filter(Boolean);
  if (parts.length <= 2) return parts.join('.');
  const lastTwo = parts.slice(-2).join('.');
  if (TWO_LABEL_SUFFIXES.has(lastTwo)) return parts.slice(-3).join('.');
  return lastTwo;
}

function isNoindex(metaRobots, xRobotsTag) {
  const combined = `${metaRobots || ''} ${xRobotsTag || ''}`.toLowerCase();
  return /\bnoindex\b/.test(combined);
}

/**
 * @param {string} target - the URL that was requested (for display only)
 * @param {object} page - probe.mjs's `page` result
 * @param {object|null} canonicalTarget - probe.mjs's `canonicalTarget` result, or null
 * @returns {{
 *   target: string, page: object|null, canonicalTarget: object|null,
 *   findings: object[], dangerCount: number, noticeCount: number,
 *   ok: boolean, incomplete: boolean,
 * }}
 */
export function buildReport(target, page, canonicalTarget = null) {
  const findings = [];
  const p = page || {};
  const incomplete = p.ok === false;

  if (!incomplete) {
    const links = Array.isArray(p.canonicalLinks) ? p.canonicalLinks : [];
    const withHref = links.filter((l) => l && l.href);

    if (links.length === 0) {
      findings.push({
        id: 'no-canonical-tag',
        severity: 'notice',
        title: 'No canonical tag found',
        detail:
          'No <link rel="canonical"> tag was found in the page\'s <head>. Search engines will infer ' +
          'a canonical URL on their own when none is given, which is not always the one you would ' +
          'choose -- an explicit tag replaces their guess with yours.',
        evidence: `fetched ${p.finalUrl}, 0 canonical link tag(s) in <head>`,
      });
    }

    if (withHref.length >= 2) {
      const distinctHrefs = [...new Set(withHref.map((l) => normalizeForCompare(l.href)))];
      if (distinctHrefs.length >= 2) {
        findings.push({
          id: 'multiple-conflicting-canonical',
          severity: 'danger',
          title: `${withHref.length} canonical tags naming ${distinctHrefs.length} different URLs`,
          detail:
            `This page's own <head> carries ${withHref.length} <link rel="canonical"> tags pointing ` +
            `at ${distinctHrefs.length} different URLs. Browsers and search engines only honor the ` +
            'first one found and ignore the rest, so this is the page contradicting itself -- often ' +
            'two systems (a CMS plugin and a hand-written template tag, for example) both emitting one.',
          evidence: withHref.map((l) => l.href).join(' | '),
        });
      }
    }

    if (withHref.length === 1) {
      const href = withHref[0].href;
      const absolute = isAbsoluteUrl(href);

      if (!absolute) {
        findings.push({
          id: 'relative-canonical-url',
          severity: 'notice',
          title: 'Canonical URL is not absolute',
          detail:
            `The canonical tag's href ("${href}") has no scheme and host. Google's own guidance is ` +
            'to use an absolute URL: a relative one leaves the protocol and host to be inferred, and ' +
            'can resolve differently than intended if the page is ever served from a different path ' +
            'or mirrored elsewhere.',
          evidence: `canonical tag href attribute: ${href}`,
        });
      }

      let abs = null;
      try {
        abs = new URL(href, p.finalUrl);
      } catch {
        abs = null;
      }
      let pageUrl = null;
      try {
        pageUrl = new URL(p.finalUrl);
      } catch {
        pageUrl = null;
      }

      if (abs && pageUrl) {
        if (abs.protocol !== pageUrl.protocol) {
          findings.push({
            id: 'protocol-mismatch-canonical',
            severity: 'notice',
            title: `Canonical uses ${abs.protocol.replace(':', '')}, page served over ${pageUrl.protocol.replace(':', '')}`,
            detail:
              "The canonical URL's scheme does not match the scheme the page itself was served over. " +
              'A mixed http/https canonical is a common leftover from a migration and can leave the ' +
              'wrong version of a page indexed.',
            evidence: `page: ${pageUrl.protocol}//${pageUrl.host} ; canonical: ${abs.protocol}//${abs.host}`,
          });
        }

        if (registrableHost(abs.hostname) !== registrableHost(pageUrl.hostname)) {
          findings.push({
            id: 'cross-domain-canonical',
            severity: 'notice',
            title: 'Canonical points to a different domain',
            detail:
              `This page's canonical tag points at ${abs.hostname}, not ${pageUrl.hostname}. That is ` +
              'a real, supported pattern for syndicated content -- but it is also exactly what a ' +
              'hardcoded staging URL or a copy-pasted template leaves behind, and either way it tells ' +
              "search engines to index the other domain's page instead of this one. Confirm it is " +
              'intentional.',
            evidence: `page host: ${pageUrl.hostname} ; canonical host: ${abs.hostname}`,
          });
        }
      }
    }
  }

  if (canonicalTarget) {
    const failed = canonicalTarget.ok === false;
    const errored = typeof canonicalTarget.status === 'number' && canonicalTarget.status >= 400;
    if (failed || errored) {
      findings.push({
        id: 'canonical-target-unreachable',
        severity: 'danger',
        title: 'Canonical URL does not return a usable page',
        detail:
          `The canonical tag points at ${canonicalTarget.requestedUrl}, and fetching it ` +
          `${failed ? `failed (${canonicalTarget.error})` : `returned HTTP ${canonicalTarget.status}`}. ` +
          'A canonical pointing at a page that errors or does not exist tells search engines to ' +
          'index a page that is not actually there.',
        evidence: failed ? `error: ${canonicalTarget.error}` : `HTTP ${canonicalTarget.status}`,
      });
    } else if (canonicalTarget.redirectCount > 0) {
      findings.push({
        id: 'canonical-target-redirects',
        severity: 'notice',
        title: 'Canonical URL redirects before resolving',
        detail:
          `The canonical tag points at ${canonicalTarget.requestedUrl}, which redirects ` +
          `${canonicalTarget.redirectCount} time(s) before reaching ${canonicalTarget.finalUrl}. A ` +
          'canonical should ideally point straight at the final resting URL, since a crawler has to ' +
          'follow the chain itself to find it.',
        evidence: `${canonicalTarget.requestedUrl} -> (${canonicalTarget.redirectCount} redirect(s)) -> ${canonicalTarget.finalUrl}`,
      });
    }

    if (!failed && isNoindex(canonicalTarget.metaRobots, canonicalTarget.xRobotsTag)) {
      const evidenceParts = [];
      if (canonicalTarget.metaRobots) evidenceParts.push(`meta robots: ${canonicalTarget.metaRobots}`);
      if (canonicalTarget.xRobotsTag) evidenceParts.push(`x-robots-tag: ${canonicalTarget.xRobotsTag}`);
      findings.push({
        id: 'canonical-target-noindex',
        severity: 'danger',
        title: 'Canonical target is itself marked noindex',
        detail:
          `The page this canonical points at (${canonicalTarget.finalUrl}) carries a noindex ` +
          'directive. A canonical tag is the instruction of which page IS the one to index -- ' +
          'pointing it at a page that says "do not index me" is a direct contradiction, and the ' +
          'practical effect is usually that neither page ends up indexed.',
        evidence: evidenceParts.join(' ; '),
      });
    }
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;

  return {
    target,
    page: page || null,
    canonicalTarget: canonicalTarget || null,
    findings,
    dangerCount,
    noticeCount,
    incomplete,
    ok: !incomplete && dangerCount === 0,
  };
}

cli/check.mjs.text:
#!/usr/bin/env node
// CLI: fetches a URL you name for real (following redirects), reads its
// canonical link tag(s), and -- when there is exactly one -- fetches that
// URL too, then reports which canonicalization misconfiguration patterns
// the evidence shows. Your machine, your network -- no request goes through
// this portfolio or anywhere but the URL(s) this check needs.
//
//   node cli/check.mjs <url> [--json] [--timeout <ms>]
//
// This sends ordinary, unauthenticated GET requests -- nothing here bypasses
// authentication, reads protected data, or does anything a browser wouldn't
// also do by visiting the URL. Exit code 0 when the page fetched
// successfully and no danger-severity finding is present; 1 when a danger
// finding is present or the fetch failed to complete (network error,
// timeout, bad URL).

import { runProbe } from './probe.mjs';
import { buildReport } from '../analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  if (report.page && report.page.ok) {
    const hop = report.page.redirectCount ? ` (${report.page.redirectCount} redirect(s))` : '';
    lines.push(`Fetched: ${report.page.finalUrl}${hop} -> HTTP ${report.page.status}`);
  }
  lines.push('');

  if (report.incomplete) {
    lines.push(`Could not fetch the page: ${report.page?.error || 'unknown error'}. Re-run once the target is reachable.`);
    lines.push('');
  } else if (report.findings.length === 0) {
    lines.push('No canonical-tag issues found in this page.');
  } else {
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidence}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from the fetch(es) above, not a full SEO audit -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbe, timeoutMs } = {}) {
  const result = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return buildReport(result.target, result.page, result.canonicalTarget);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node cli/check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const report = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, page: report.page, canonicalTarget: report.canonicalTarget }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

cli/probe.mjs.text:
// Sends the real HTTP request(s) this check depends on: one GET to the URL a
// caller names, following redirects itself so the report can say how many
// hops it took, then -- only when the page carries exactly one absolute,
// non-self-referencing canonical link -- a second GET to that canonical URL
// to see whether it actually resolves to a usable, indexable page.
//
// Node's built-in http/https clients are used deliberately, not fetch() from
// a browser tab: reading another origin's response body and headers from
// inside a page is CORS-gated, and most sites set no
// Access-Control-Allow-Origin at all, so a browser tab could not reliably
// read this evidence even for a URL you own. That is the same "browser
// can't do the full check itself" split `cors-misconfig-check` and
// `security-headers-check` already document, for a different underlying
// reason each time.
//
// This module only ever talks to the URL(s) a caller names (the target, and
// at most one canonical-URL follow-up). It makes no other network call,
// reads no local files, and sends nothing anywhere else.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';

const DEFAULT_TIMEOUT_MS = 10_000;
const MAX_REDIRECTS = 5;
const MAX_BODY_BYTES = 2_000_000; // only <head> matters; no real page needs more to find it
const USER_AGENT =
  'canonical-tag-check/1 (+https://duncan-haywood.github.io/monorepo-projects/canonical-tag-check/)';

function headerValue(headers, name) {
  const value = headers[name.toLowerCase()];
  if (value == null) return null;
  return Array.isArray(value) ? value.join(', ') : String(value);
}

function singleGet(url, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(url);
    } catch (err) {
      resolve({ ok: false, status: null, headers: {}, body: '', error: `invalid URL: ${err.message}` });
      return;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      resolve({ ok: false, status: null, headers: {}, body: '', error: `unsupported scheme: ${parsed.protocol}` });
      return;
    }

    const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const req = requester(
      parsed,
      { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: 'text/html,*/*' }, timeout: timeoutMs },
      (res) => {
        const chunks = [];
        let size = 0;
        res.on('data', (chunk) => {
          if (size >= MAX_BODY_BYTES) return;
          chunks.push(chunk);
          size += chunk.length;
        });
        res.on('end', () => {
          finish({
            ok: true,
            status: res.statusCode ?? null,
            headers: {
              location: headerValue(res.headers, 'location'),
              'x-robots-tag': headerValue(res.headers, 'x-robots-tag'),
              'content-type': headerValue(res.headers, 'content-type'),
            },
            body: Buffer.concat(chunks).toString('utf8'),
            error: null,
          });
        });
        res.on('error', (err) => finish({ ok: false, status: res.statusCode ?? null, headers: {}, body: '', error: err.message }));
      },
    );
    req.on('timeout', () => req.destroy(new Error('timed out')));
    req.on('error', (err) => finish({ ok: false, status: null, headers: {}, body: '', error: err.message }));
    req.end();
  });
}

/**
 * GET `url`, following up to MAX_REDIRECTS 3xx `Location` redirects itself
 * (Node's http/https clients do not follow redirects automatically). Returns
 * the final response plus how many hops it took to get there.
 */
export async function fetchFollowingRedirects(url, opts = {}) {
  let current = url;
  let redirectCount = 0;
  for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
    const res = await singleGet(current, opts);
    if (!res.ok) {
      return { ...res, requestedUrl: url, finalUrl: current, redirectCount };
    }
    if (res.status >= 300 && res.status < 400 && res.headers.location) {
      let next;
      try {
        next = new URL(res.headers.location, current).toString();
      } catch {
        return { ...res, requestedUrl: url, finalUrl: current, redirectCount };
      }
      current = next;
      redirectCount += 1;
      continue;
    }
    return { ...res, requestedUrl: url, finalUrl: current, redirectCount };
  }
  return {
    ok: false,
    status: null,
    headers: {},
    body: '',
    error: 'too many redirects',
    requestedUrl: url,
    finalUrl: current,
    redirectCount,
  };
}

function extractHead(html) {
  const m = /<head[^>]*>([\s\S]*?)<\/head>/i.exec(html || '');
  return m ? m[1] : html || '';
}

function attrValue(match) {
  if (!match) return null;
  return match[1] ?? match[2] ?? match[3] ?? null;
}

const LINK_TAG_RE = /<link\b[^>]*>/gi;
const REL_ATTR_RE = /\brel\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/i;
const HREF_ATTR_RE = /\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/i;
const META_ROBOTS_TAG_RE = /<meta\b[^>]*\bname\s*=\s*(?:"robots"|'robots')[^>]*>/gi;
const CONTENT_ATTR_RE = /\bcontent\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/i;

/** Every canonical `<link>` tag found in the document's `<head>`, in
 * document order, as `{ href, raw }`. `rel` is matched case-insensitively
 * and by exact token (a `rel="alternate canonical"` list still counts;
 * `rel="noncanonical"` does not). */
export function extractCanonicalLinks(html) {
  const out = [];
  const head = extractHead(html);
  for (const tagMatch of head.matchAll(LINK_TAG_RE)) {
    const tag = tagMatch[0];
    const rel = attrValue(tag.match(REL_ATTR_RE));
    if (!rel) continue;
    const rels = rel.toLowerCase().trim().split(/\s+/);
    if (!rels.includes('canonical')) continue;
    out.push({ href: attrValue(tag.match(HREF_ATTR_RE)), raw: tag });
  }
  return out;
}

/** Every `<meta name="robots" content="...">` tag's content, joined with
 * ", " -- or null if none is present. */
export function extractMetaRobots(html) {
  const head = extractHead(html);
  const contents = [];
  for (const tagMatch of head.matchAll(META_ROBOTS_TAG_RE)) {
    const content = attrValue(tagMatch[0].match(CONTENT_ATTR_RE));
    if (content) contents.push(content);
  }
  return contents.length ? contents.join(', ') : null;
}

function normalizeUrl(u) {
  try {
    const p = new URL(u);
    p.hash = '';
    if ((p.protocol === 'http:' && p.port === '80') || (p.protocol === 'https:' && p.port === '443')) p.port = '';
    return p.toString().replace(/\/$/, '');
  } catch {
    return u;
  }
}

/**
 * Fetches `targetUrl`, extracts its canonical link tag(s) and meta-robots
 * directive, and -- only when the page names exactly one absolute,
 * non-self-referencing canonical -- fetches that URL too, to see whether it
 * actually resolves to a usable, indexable page.
 *
 * @returns {{ target: string, page: object, canonicalTarget: object|null }}
 */
export async function runProbe(targetUrl, opts = {}) {
  const fetched = await fetchFollowingRedirects(targetUrl, opts);
  const canonicalLinks = fetched.ok ? extractCanonicalLinks(fetched.body) : [];
  const metaRobots = fetched.ok ? extractMetaRobots(fetched.body) : null;

  const page = {
    requestedUrl: fetched.requestedUrl,
    finalUrl: fetched.finalUrl,
    redirectCount: fetched.redirectCount,
    ok: fetched.ok,
    status: fetched.status,
    error: fetched.error,
    xRobotsTag: fetched.headers?.['x-robots-tag'] ?? null,
    metaRobots,
    canonicalLinks,
  };

  let canonicalTarget = null;
  if (fetched.ok && canonicalLinks.length === 1 && canonicalLinks[0].href) {
    let abs = null;
    try {
      abs = new URL(canonicalLinks[0].href, fetched.finalUrl).toString();
    } catch {
      abs = null;
    }
    if (abs && normalizeUrl(abs) !== normalizeUrl(fetched.finalUrl)) {
      const target = await fetchFollowingRedirects(abs, opts);
      canonicalTarget = {
        requestedUrl: abs,
        finalUrl: target.finalUrl,
        redirectCount: target.redirectCount,
        ok: target.ok,
        status: target.status,
        error: target.error,
        xRobotsTag: target.headers?.['x-robots-tag'] ?? null,
        metaRobots: target.ok ? extractMetaRobots(target.body) : null,
      };
    }
  }

  return { target: targetUrl, page, canonicalTarget };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'canonical-tag-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
